flowchart TD
  start(["Início: Avaliar oração com 'haver'"]) --> dec_sentido{"Verbo 'haver' está no sentido de 'existir'?"}
  dec_sentido -- "Não" --> res_outro["Substituição Direta Não Aplicável"]
  dec_sentido -- "Sim" --> proc_reestruturacao["Reestruturação Sintática:<br/>OD vira Sujeito | VTD vira VI"]
  proc_reestruturacao --> dec_numero{"Qual o número do novo Sujeito?"}
  dec_numero -- "Singular" --> dec_banca_sing{"Banca manteve 'existir' no singular?"}
  dec_banca_sing -- "Sim" --> res_sing_ok["Item Gramaticalmente Correto<br/>(ex.: 'Existia uma razão')"]
  dec_banca_sing -- "Não" --> res_sing_err["Item Gramaticalmente Incorreto<br/>(flexão indevida no plural)"]
  dec_numero -- "Plural" --> dec_banca_plur{"Banca flexionou 'existir' no plural?"}
  dec_banca_plur -- "Sim" --> res_plur_ok["Item Gramaticalmente Correto<br/>(ex.: 'Existiam razões')"]
  dec_banca_plur -- "Não" --> res_plur_err["Item Gramaticalmente Incorreto<br/>(erro: manter no singular)"]
